import { isNil } from 'lodash';

interface UseInputTrackValueProps {
    dataTrackValue?: string;
    value?: any;
}

export const useInputTrackValue = ({ dataTrackValue, value }: UseInputTrackValueProps) => {
    if (dataTrackValue !== undefined) {
        return dataTrackValue;
    }
    let valueStringValue: string;

    if (!isNil(value)) {
        if (Array.isArray(value)) {
            valueStringValue = value.filter((item) => !isNil(item)).toString();
        } else if (typeof value === 'object') {
            valueStringValue = Object.entries(value)
                .map(([key, item]) => `${key}:${Array.isArray(item) ? item.filter((value) => !isNil(value)) : item}`)
                .toString();
        } else {
            valueStringValue = String(value);
        }
        return valueStringValue;
    }
    return undefined;
};
